## Read-Replica DataSource Routing

```java
// Routing key holder
public class DataSourceContextHolder {
    private static final ThreadLocal<String> context = new ThreadLocal<>();

    public static void useReplica()  { context.set("replica"); }
    public static void usePrimary()  { context.set("primary"); }
    public static void clear()       { context.remove(); }
    public static String getCurrent() { return context.get(); }
}

// Routing data source
@Bean
public DataSource dataSource(
        @Qualifier("primaryDataSource") DataSource primary,
        @Qualifier("replicaDataSource") DataSource replica) {

    return new AbstractRoutingDataSource() {
        @Override
        protected Object determineCurrentLookupKey() {
            return DataSourceContextHolder.getCurrent();
        }
        @Override
        public void afterPropertiesSet() {
            setDefaultTargetDataSource(primary);
            setTargetDataSources(Map.of("primary", primary, "replica", replica));
            super.afterPropertiesSet();
        }
    };
}

// AOP: route readOnly transactions to replica
@Aspect
@Component
public class ReplicaRoutingAspect {
    @Around("@annotation(tx)")
    public Object route(ProceedingJoinPoint pjp, Transactional tx) throws Throwable {
        if (tx.readOnly()) {
            DataSourceContextHolder.useReplica();
        } else {
            DataSourceContextHolder.usePrimary();
        }
        try {
            return pjp.proceed();
        } finally {
            DataSourceContextHolder.clear();
        }
    }
}
```

