    primary:
      url: jdbc:postgresql://primary.xxxx.ap-south-1.rds.amazonaws.com:5432/appdb
    replica:
      url: jdbc:postgresql://replica.xxxx.ap-south-1.rds.amazonaws.com:5432/appdb
      # Aurora reader endpoint (load balances across all replicas):
      # url: jdbc:postgresql://cluster.cluster-ro-xxxx.ap-south-1.rds.amazonaws.com:5432/appdb
```

```java
// Service usage — transparent to developer
@Service
public class ProductService {

    @Transactional(readOnly = true)  // routed to replica
    public List<ProductDTO> search(String keyword) {
        return productRepo.findByNameContaining(keyword);
    }

    @Transactional  // routed to primary (write)
    public Product create(CreateProductRequest req) {
        return productRepo.save(Product.from(req));
    }
}
